mapper.select:
WITH TEMP AS ( SELECT * FROM( select sys_data_process_mark.*,rank() over(partition by workflow_id order by HIS_NO desc) as rank from sys_data_process_mark where page_id in ('FinBondTargetAsset002','FinProjectTargetAsset002','FinTenderBondTargetAsset002','FinDepositTarget002', 'FinFundTarget002','FinStockInfo002','FinOptionTarget002','FinPlanNetAsset002','FinPlanProfitAsset002','FinPlanAssetC002') ) WHERE rank = 1 ) select launchUser, nvl(finprodName,finprodAbbr) finprodName, finprodId, nextUser, createTaskTime, instCode from( SELECT T.create_user as launchUser, case when temp.page_id = 'FinStockInfo002' then nvl(replace(replace(to_char(REGEXP_SUBSTR(temp.business_data,'"finprodId":"[^"]+"',1,1)),'"finprodId":"',''),'"',''),temp.business_data_pk1) when temp.page_id = 'FinOptionTarget002' then temp.business_data_pk1 else replace(replace(to_char(REGEXP_SUBSTR(temp.business_data,'"finprodId":"[^"]+"',1,1)),'"finprodId":"',''),'"','') end as finprodId, case when temp.page_id = 'FinOptionTarget002' then replace(replace(to_char(REGEXP_SUBSTR(temp.business_data,'"targetName":"[^"]+"',1,1)),'"targetName":"',''),'"','') else replace(replace(to_char(REGEXP_SUBSTR(temp.business_data,'"finprodName":"[^"]+"',1,1)),'"finprodName":"',''),'"','') end as finprodName, case when temp.page_id = 'FinOptionTarget002' then '' else replace(replace(to_char(REGEXP_SUBSTR(temp.business_data,'"finprodAbbr":"[^"]+"',1,1)),'"finprodAbbr":"',''),'"','') end as finprodAbbr, T.NEXT_USER AS nextUser, T.CRT_DATE AS createTaskTime, sd.institution_code instCode FROM SYS_WFL_BUSINESS_LIST T INNER JOIN TEMP on T.seq_no = temp.workflow_id and T.PROCESS_STATE != 'END' LEFT JOIN SYS_USER su on T.CRT_USER =su.user_name LEFT JOIN SYS_DEPARTMENT sd ON SU.DEPT_CODE = sd.Dept_Code WHERE T.crt_date <= #{checkDate,jdbcType=DATE}
and (temp.page_id in ('FinBondTargetAsset002','FinTenderBondTargetAsset002','FinFundTarget002','FinStockInfo002') or sd.institution_code = #{instCode,jdbcType=VARCHAR})
)
